(2509069, 344459, 12733, '<td valign="top">That''s some menacing shadow! Nice take on the challenge.</td>', 'That''s some menacing shadow! Nice take on the challenge.', '2006-06-12 11:26:31.000000', NULL, 1),
(2509072, 346255, 12733, '<td valign="top">I like the picture, but I have to drop my rating a bit because the shadow is really a small part of the picture. Indeed, it takes some looking to find the significant shadow at all!</td>', 'I like the picture, but I have to drop my rating a bit because the shadow is really a small part of the picture. Indeed, it takes some looking to find the significant shadow at all!', '2006-06-12 11:29:16.000000', NULL, 1),
