(2519404, 346415, 27133, '<td valign="top">Very creative...good work.</td>', 'Very creative...good work.', '2006-06-15 07:51:58.000000', NULL, 1),
(2519406, 345842, 27133, '<td valign="top">Ahh now...this is good.</td>', 'Ahh now...this is good.', '2006-06-15 07:52:11.000000', NULL, 1),
(2519407, 346186, 30364, '<td valign="top">I think the fact that he''s sitting down (rather than just passing through) makes this seem even more laden with symbolism than it might otherwise be.  The diagonals dominate, of course, but the big rectangles on the wall also <br/>seem critical to me ... they suggest video/TV screens and, with the diagonal bars across them, make the image about imperfect communication for me.  Which of course means the title is particularly pleasing.  8.</td>', 'I think the fact that he''s sitting down (rather than just passing through) makes this seem even more laden with symbolism than it might otherwise be.  The diagonals dominate, of course, but the big rectangles on the wall also seem critical to me ... they suggest video/TV screens and, with the diagonal bars across them, make the image about imperfect communication for me.  Which of course means the title is particularly pleasing.  8.', '2006-06-15 07:52:16.000000', NULL, 1),
(2519408, 346410, 27133, '<td valign="top">Very angular...it makes you stop and look that bit longer...and that means it is a success.</td>', 'Very angular...it makes you stop and look that bit longer...and that means it is a success.', '2006-06-15 07:52:47.000000', NULL, 1),
