(2519518, 345763, 27133, '<td valign="top">Good abstract image.</td>', 'Good abstract image.', '2006-06-15 08:24:20.000000', NULL, 1),
(2519519, 345387, 30364, '<td valign="top">Clever.  It''s perhaps the most witty use of a shadow in this challenge.  Genetic pedants might say it''s not really a double helix (more of a twin helix) but even they would have to admire the steps treads so convincingly representing the base molecular bonds.  Plus a bonus point for including the pair of birds. 8.</td>', 'Clever.  It''s perhaps the most witty use of a shadow in this challenge.  Genetic pedants might say it''s not really a double helix (more of a twin helix) but even they would have to admire the steps treads so convincingly representing the base molecular bonds.  Plus a bonus point for including the pair of birds. 8.', '2006-06-15 08:24:36.000000', NULL, 1),
(2519520, 346005, 27133, '<td valign="top">I like the angle and the idea...but could do with a bit more sharpness on the petals.</td>', 'I like the angle and the idea...but could do with a bit more sharpness on the petals.', '2006-06-15 08:24:40.000000', NULL, 1),
