(2519530, 346096, 27133, '<td valign="top">Ohhhhhhhhhhhhh this is perfect....love it.</td>', 'Ohhhhhhhhhhhhh this is perfect....love it.', '2006-06-15 08:27:16.000000', NULL, 1),
