(2521394, 346254, 50982, '<td valign="top">Lots of halo issues around both pieces and not sure if it''s natural noise or if you just made it grainy. Whatever it is, definitely doesn''t help.</td>', 'Lots of halo issues around both pieces and not sure if it''s natural noise or if you just made it grainy. Whatever it is, definitely doesn''t help.', '2006-06-15 21:57:16.000000', NULL, 1),
(2521395, 346076, 46782, '<td valign="top">I like this image but I have seen it done before - no disrespect, your version is fine and I won''t subtract any points in my score. Good job</td>', 'I like this image but I have seen it done before - no disrespect, your version is fine and I won''t subtract any points in my score. Good job', '2006-06-15 21:57:59.000000', NULL, 1),
