INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2527612, 346303, 53964, '<td valign="top">I voted this one high because of the subtlety... it was refreshing change :)</td>', 'I voted this one high because of the subtlety... it was refreshing change :)', '2006-06-19 02:13:14.000000', NULL, 0),
(2527619, 346474, 41337, '<td valign="top">Incredibly creative. Congrats!</td>', 'Incredibly creative. Congrats!', '2006-06-19 02:17:25.000000', NULL, 0),
(2527637, 345822, 30982, '<td valign="top">This was one of three 10s I gave in this challenge.  Shadows are very well integrated into the feel of the whole picture.  Without them, it wouldn''t be the same.  Lower finish that I''d have expected but this is a very powerful picture.</td>', 'This was one of three 10s I gave in this challenge.  Shadows are very well integrated into the feel of the whole picture.  Without them, it wouldn''t be the same.  Lower finish that I''d have expected but this is a very powerful picture.', '2006-06-19 02:36:59.000000', NULL, 0),
(2527658, 346415, 60165, '<td valign="top">This is a night shot, long exposure. The light is from a bright lamp shining over the entire pool area - with some warmth to the colours, it looks a bit more like day, but because of the light source, the shadow is very well-defined. The shadow of the person is me, trying to stand still for self timer plus 8 seconds. I was almost not let in, had to do it quickly, without a tripod, so had to improvise.<br/> <br/>Idea might be good but quality of the shot is ... not worth more than 4.788 and 134/154, so it is fair enough for this effort. But I wanted to enter a challenge, and was too impatient to wait for the next one ...<br/>feet no need for the critique club on this one!<br/> <br/>Next one is running close to 6.0 (framing), whilst "Desolation" was another desparate attempt. Bokeh I haven''t done yet but I have a rather good idea so hopes are high on that one!<br/> <br/></td>', 'This is a night shot, long exposure. The light is from a bright lamp shining over the entire pool area - with some warmth to the colours, it looks a bit more like day, but because of the light source, the shadow is very well-defined. The shadow of the person is me, trying to stand still for self timer plus 8 seconds. I was almost not let in, had to do it quickly, without a tripod, so had to improvise. Idea might be good but quality of the shot is ... not worth more than 4.788 and 134/154, so it is fair enough for this effort. But I wanted to enter a challenge, and was too impatient to wait for the next one ...feet no need for the critique club on this one! Next one is running close to 6.0 (framing), whilst "Desolation" was another desparate attempt. Bokeh I haven''t done yet but I have a rather good idea so hopes are high on that one! ', '2006-06-19 02:43:46.000000', NULL, 0),
(2527660, 346171, 30982, '<td valign="top">I gave this a 10 and really do think it should have ribboned.</td>', 'I gave this a 10 and really do think it should have ribboned.', '2006-06-19 02:45:12.000000', NULL, 0),
(2527661, 346474, 15711, '<td valign="top">Congrats.  Just stunning and I totally "got it."</td>', 'Congrats.  Just stunning and I totally "got it."', '2006-06-19 02:45:22.000000', NULL, 0),
(2527664, 346177, 30982, '<td valign="top">Congrats on an excellent shot and an excellent finish!  And beating out that Tim guy, too.  :-)</td>', 'Congrats on an excellent shot and an excellent finish!  And beating out that Tim guy, too.  :-)', '2006-06-19 02:47:37.000000', NULL, 0),
(2527665, 345927, 15711, '<td valign="top">Congrats!!!  Really a terrific image.</td>', 'Congrats!!!  Really a terrific image.', '2006-06-19 02:47:59.000000', NULL, 0),
