(2527675, 346192, 15711, '<td valign="top">I felt this deserved top 10.</td>', 'I felt this deserved top 10.', '2006-06-19 02:50:34.000000', NULL, 0),
(2527685, 344856, 34659, '<td valign="top">EXCELLENT Phillip!  WooHoo!  Congrats on 5th place.  Well deserved with this gorgeous shot.  :-)</td>', 'EXCELLENT Phillip!  WooHoo!  Congrats on 5th place.  Well deserved with this gorgeous shot.  :-)', '2006-06-19 03:00:53.000000', NULL, 0),
(2527686, 346477, 34659, '<td valign="top">Congratulations on 4th place.  This is such a cool shot.  Well done.</td>', 'Congratulations on 4th place.  This is such a cool shot.  Well done.', '2006-06-19 03:01:30.000000', NULL, 0),
(2527698, 344856, 16004, '<td valign="top">i thought this was startlingly starkly beautiful, and seriously meant my congrats on the blue comment, because i naturally thought it was a given.  the surreal / ethereal effect of the white ground, the sharp details of the trees and the gloriously lush blue sky to me meant that it had everything going for it and a ribbon was in the bag.  i guess you lost out a little bit because the shadows aren''t too significant an aspect of the overall composition.  still, congrats on the still very honourable honourable mention.</td>', 'i thought this was startlingly starkly beautiful, and seriously meant my congrats on the blue comment, because i naturally thought it was a given.  the surreal / ethereal effect of the white ground, the sharp details of the trees and the gloriously lush blue sky to me meant that it had everything going for it and a ribbon was in the bag.  i guess you lost out a little bit because the shadows aren''t too significant an aspect of the overall composition.  still, congrats on the still very honourable honourable mention.', '2006-06-19 03:25:24.000000', NULL, 0),
(2527709, 345927, 53964, '<td valign="top">This was one of my extremely rare 10''s. The one unshuttered window just added the finishing touch for a great shot. Congrats! :D</td>', 'This was one of my extremely rare 10''s. The one unshuttered window just added the finishing touch for a great shot. Congrats! :D', '2006-06-19 03:36:07.000000', NULL, 0),
